import { drizzleAdapter } from "@better-auth/drizzle-adapter";
import { oauthProvider } from "@better-auth/oauth-provider";
import { betterAuth } from "better-auth/minimal";
import { jwt } from "better-auth/plugins/jwt";
import { createDb } from "../db";
import * as authSchema from "../db/auth-schema";

export interface AuthEnvironment {
  DB: D1Database;
  BETTER_AUTH_SECRET: string;
  BETTER_AUTH_URL: string;
}

export function createAuth(environment: AuthEnvironment) {
  const resourceIdentifier = `${environment.BETTER_AUTH_URL}/api`;

  return betterAuth({
    appName: "Shui",
    basePath: "/api/auth",
    baseURL: environment.BETTER_AUTH_URL,
    database: drizzleAdapter(createDb(environment.DB), {
      provider: "sqlite",
      schema: authSchema,
      transaction: false,
    }),
    disabledPaths: ["/token"],
    emailAndPassword: {
      enabled: true,
    },
    plugins: [
      jwt(),
      oauthProvider({
        allowDynamicClientRegistration: false,
        allowUnauthenticatedClientRegistration: false,
        clientRegistrationAllowedResources: [resourceIdentifier],
        clientRegistrationDefaultResources: [resourceIdentifier],
        consentPage: "/consent",
        enforcePerClientResources: true,
        grantTypes: ["authorization_code", "client_credentials"],
        loginPage: "/sign-in",
        resources: [
          {
            accessTokenTtl: 3600,
            allowedScopes: ["openid", "profile", "email", "api:read"],
            identifier: resourceIdentifier,
            name: "Shui API",
          },
        ],
        scopes: ["openid", "profile", "email", "api:read"],
      }),
    ],
    secret: environment.BETTER_AUTH_SECRET,
    telemetry: {
      enabled: false,
    },
    trustedOrigins: [environment.BETTER_AUTH_URL],
  });
}
import { Elysia, t } from "elysia";

import { type AuthEnvironment, createAuth } from "./auth";

export function createApiApp(environment: AuthEnvironment) {
  const auth = createAuth(environment);

  return new Elysia({ aot: false, prefix: "/api" })
    .get("/health", () => ({ service: "shui-api", status: "ok" as const }), {
      response: t.Object({
        service: t.String(),
        status: t.Literal("ok"),
      }),
    })
    .head("/health", () => new Response(null, { status: 204 }))
    .mount(auth.handler);
}

export type ApiApp = ReturnType<typeof createApiApp>;
import { Button, Input, LayerCard } from "@cloudflare/kumo";
import { useForm } from "@tanstack/react-form";
import { useMutation, useQueryClient } from "@tanstack/react-query";

import { authClient } from "../lib/auth-client";
import { authQueryKeys } from "../lib/auth-queries";

export function AuthPage() {
  const queryClient = useQueryClient();
  const signIn = useMutation({
    mutationFn: async (value: { email: string; password: string }) => {
      const { data, error } = await authClient.signIn.email(value);

      if (error) {
        throw error;
      }

      return data;
    },
    mutationKey: ["auth", "sign-in"],
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: authQueryKeys.session });
    },
    retry: false,
  });
  const form = useForm({
    defaultValues: { email: "", password: "" },
    onSubmit: ({ value }) => {
      signIn.mutate(value);
    },
  });
  const message = signIn.isError
    ? "The credentials could not be verified."
    : signIn.isSuccess
      ? "Signed in."
      : undefined;

  return (
    <section className="mx-auto max-w-xl px-5 py-14 sm:px-8 sm:py-20">
      <p className="text-sm font-medium uppercase text-(--tangerine)">Welcome back</p>
      <h1 className="mt-4 font-display text-2xl font-semibold leading-none text-kumo-strong">
        shui にログインする
      </h1>
      <LayerCard className="mt-10 bg-kumo-elevated px-5 py-4 ring ring-kumo-line">
        <h2 className="text-2xl font-semibold text-kumo-strong">サインイン</h2>
        <p className="mt-2 text-sm text-kumo-subtle">
          M0 uses Better Auth email/password as its first protocol probe.
        </p>
        <form
          className="mt-6 space-y-5"
          onSubmit={(event) => {
            event.preventDefault();
            void form.handleSubmit();
          }}
        >
          <form.Field name="email">
            {(field) => (
              <Input
                id="email"
                autoComplete="email"
                className="text-sm transition-none"
                label="メールアドレス"
                onChange={(event) => field.handleChange(event.target.value)}
                value={field.state.value}
              />
            )}
          </form.Field>
          <form.Field name="password">
            {(field) => (
              <Input
                id="password"
                autoComplete="current-password"
                className="text-sm transition-none"
                label="パスワード"
                onChange={(event) => field.handleChange(event.target.value)}
                type="password"
                value={field.state.value}
              />
            )}
          </form.Field>
          <Button
            aria-busy={signIn.isPending}
            className="w-full justify-center text-sm transition-none"
            disabled={signIn.isPending}
            type="submit"
            variant="primary"
          >
            {signIn.isPending ? "Signing in..." : "Continue"}
          </Button>
          {message ? (
            <p className="text-sm text-kumo-brand" role={signIn.isError ? "alert" : "status"}>
              {message}
            </p>
          ) : null}
        </form>
      </LayerCard>
    </section>
  );
}

